import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

scale_clamp_source = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>

// Elementwise scaling by a scalar
__global__ void scale_kernel(const float* __restrict__ input, float* __restrict__ output, float scale, int size) {
    int idx = blockDim.x * blockIdx.x + threadIdx.x;
    if (idx < size) {
        output[idx] = input[idx] * scale;
    }
}

// Elementwise clamp
__global__ void clamp_kernel(const float* __restrict__ input, float* __restrict__ output, float min_val, float max_val, int size) {
    int idx = blockDim.x * blockIdx.x + threadIdx.x;
    if (idx < size) {
        float val = input[idx];
        val = val < min_val ? min_val : val;
        val = val > max_val ? max_val : val;
        output[idx] = val;
    }
}

torch::Tensor scale_tensor_cuda(torch::Tensor x, float scale) {
    auto out = torch::zeros_like(x);
    int size = x.numel();
    const int threads = 256;
    const int blocks = (size + threads - 1) / threads;

    scale_kernel<<<blocks, threads>>>(x.data_ptr<float>(), out.data_ptr<float>(), scale, size);
    return out;
}

torch::Tensor clamp_tensor_cuda(torch::Tensor x, float min_val, float max_val) {
    auto out = torch::zeros_like(x);
    int size = x.numel();
    const int threads = 256;
    const int blocks = (size + threads - 1) / threads;

    clamp_kernel<<<blocks, threads>>>(x.data_ptr<float>(), out.data_ptr<float>(), min_val, max_val, size);
    return out;
}
"""

scale_clamp_cpp_source = r"""
torch::Tensor scale_tensor_cuda(torch::Tensor x, float scale);
torch::Tensor clamp_tensor_cuda(torch::Tensor x, float min_val, float max_val);
"""

scale_clamp = load_inline(
    name="scale_clamp",
    cpp_sources=scale_clamp_cpp_source,
    cuda_sources=scale_clamp_source,
    functions=["scale_tensor_cuda", "clamp_tensor_cuda"],
    verbose=True
)

class ModelNew(nn.Module):
    """
    Optimized model that performs a transposed 3D convolution, then uses custom CUDA
    operations for elementwise scaling and clamping, while using PyTorch for
    max pooling and global average pooling.
    """
    def __init__(self, in_channels, out_channels, kernel_size, stride, padding, scale, maxpool_kernel_size):
        super(ModelNew, self).__init__()
        self.conv_transpose = nn.ConvTranspose3d(in_channels, out_channels, kernel_size,
                                                 stride=stride, padding=padding)
        self.scale_val = scale
        self.maxpool = nn.MaxPool3d(kernel_size=maxpool_kernel_size)
        self.global_avg_pool = nn.AdaptiveAvgPool3d((1, 1, 1))
        self.clamp_min = 0.0
        self.clamp_max = 1.0

    def forward(self, x):
        x = self.conv_transpose(x)
        x = scale_clamp.scale_tensor_cuda(x, self.scale_val)
        x = self.maxpool(x)
        x = self.global_avg_pool(x)
        x = scale_clamp.clamp_tensor_cuda(x, self.clamp_min, self.clamp_max)
        return x
